import { Link } from 'react-router-dom';
import { useStore } from '../context/StoreContext';

function money(value, currency = 'USD') {
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(value || 0);
  } catch {
    return `${currency} ${value || 0}`;
  }
}

function CartPage() {
  const { cart, updateQuantity, removeFromCart, cartSubtotal, discount, tax, delivery, cartTotal, clearCart } = useStore();

  return (
    <section className="section">
      <div className="container">
        <div className="breadcrumb"><span>Home</span> › <span>Shopping Cart</span></div>
        <div className="section-header">
          <div>
            <span className="eyebrow">Shopping cart</span>
            <h1 className="title">Review your selected items</h1>
          </div>
          {cart.length > 0 && <button className="btn btn-danger" type="button" onClick={clearCart}>Clear Cart</button>}
        </div>

        {cart.length === 0 ? (
          <div className="empty-state">
            <h3>Your cart is empty</h3>
            <p>Add live API products to continue to checkout.</p>
            <Link className="btn btn-primary" style={{ marginTop: 16 }} to="/products">Continue Shopping</Link>
          </div>
        ) : (
          <div className="checkout-layout" style={{ display: 'grid', gridTemplateColumns: '1fr 360px', gap: 22, alignItems: 'start' }}>
            <div className="card" style={{ padding: 22 }}>
              <div style={{ display: 'grid', gap: 14 }}>
                {cart.map((item) => (
                  <article className="cart-item" key={item.id} style={{ display: 'grid', gridTemplateColumns: '90px 1fr auto auto', gap: 14, alignItems: 'center', borderBottom: '1px solid var(--border)', paddingBottom: 14 }}>
                    <div style={{ background: 'var(--panel-2)', borderRadius: 16, height: 78, display: 'grid', placeItems: 'center', overflow: 'hidden' }}>
                      {item.image ? <img src={item.image} alt={item.title} style={{ width: '100%', height: '100%', objectFit: 'contain', padding: 8 }} /> : '📦'}
                    </div>
                    <div>
                      <h3 style={{ margin: '0 0 6px' }}>{item.title}</h3>
                      <p className="subtitle" style={{ margin: 0 }}>{item.brand} · {item.category} · {item.source}</p>
                      <strong>{money(item.price, item.currency)}</strong>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <button className="btn btn-secondary" type="button" onClick={() => updateQuantity(item.id, item.quantity - 1)}>−</button>
                      <strong>{item.quantity}</strong>
                      <button className="btn btn-secondary" type="button" onClick={() => updateQuantity(item.id, item.quantity + 1)}>+</button>
                    </div>
                    <button className="btn btn-danger" type="button" onClick={() => removeFromCart(item.id)}>Remove</button>
                  </article>
                ))}
              </div>
            </div>

            <aside className="order-summary card" style={{ padding: 22 }}>
              <h3>Order Summary</h3>
              <div className="summary-total" style={{ display: 'grid', gridTemplateColumns: '1fr auto', gap: 10, marginTop: 16 }}>
                <span>Subtotal</span><strong>{money(cartSubtotal)}</strong>
                <span>Discount</span><strong>{money(discount)}</strong>
                <span>Tax</span><strong>{money(tax)}</strong>
                <span>Delivery</span><strong>{delivery === 0 ? 'Free' : money(delivery)}</strong>
                <span>Total</span><strong>{money(cartTotal)}</strong>
              </div>
              <input className="input" style={{ marginTop: 18, width: '100%', padding: 12, borderRadius: 14, border: '1px solid var(--border)', background: 'var(--panel-2)', color: 'var(--text)' }} placeholder="Coupon code" aria-label="Coupon code" />
              <Link className="btn btn-primary" style={{ width: '100%', marginTop: 12 }} to="/checkout">Proceed to Checkout</Link>
              <p className="subtitle">🔒 Secure checkout and clear confirmation before payment.</p>
            </aside>
          </div>
        )}
      </div>
    </section>
  );
}

export default CartPage;
